import React, { useState } from "react";

export default function App() {
  const [form, setForm] = useState({
    disease: "",
    intent: "",
    location: ""
  });

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleRun = async () => {
    setLoading(true);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(form)
      });

      const result = await res.json();
      setData(result);
    } catch (err) {
      console.error(err);
      alert("Backend connection error");
    }

    setLoading(false);
  };

  return (
    <div style={{ display: "flex", height: "100vh", background: "#0B1220", color: "white" }}>

      {/* LEFT PANEL */}
      <div style={{ width: "250px", padding: "20px", borderRight: "1px solid #333" }}>
        <h2>🧠 AI Copilot</h2>

        <p>📄 Papers: {data?.publications?.length || 0}</p>
        <p>🧪 Trials: {data?.clinical_trials?.length || 0}</p>
      </div>

      {/* CENTER PANEL */}
      <div style={{ flex: 1, padding: "20px" }}>
        <h2>Medical Research Query</h2>

        <input name="disease" placeholder="Disease" onChange={handleChange} style={input} />
        <input name="intent" placeholder="Intent (treatment / diagnosis)" onChange={handleChange} style={input} />
        <input name="location" placeholder="Location" onChange={handleChange} style={input} />

        <button onClick={handleRun} style={button}>
          {loading ? "Running..." : "Run Analysis"}
        </button>

        {data && (
          <div style={card}>
            <h3>🤖 AI Summary</h3>
            <p>{data.summary}</p>
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div style={{ width: "350px", padding: "20px", borderLeft: "1px solid #333", overflowY: "auto" }}>

        <h3>📄 Research Papers</h3>
        {data?.publications?.map((p, i) => (
          <div key={i} style={card}>
            <strong>{p.title}</strong>
            <p style={{ fontSize: "12px" }}>{p.source} • {p.year}</p>
          </div>
        ))}

        <h3>🧪 Clinical Trials</h3>
        {data?.clinical_trials?.map((t, i) => (
          <div key={i} style={card}>
            <strong>{t.title}</strong>
            <p style={{ fontSize: "12px" }}>{t.status}</p>
          </div>
        ))}
      </div>

    </div>
  );
}

const input = {
  display: "block",
  margin: "10px 0",
  padding: "10px",
  width: "300px"
};

const button = {
  padding: "10px 20px",
  background: "#3b82f6",
  color: "white",
  border: "none",
  marginTop: "10px",
  cursor: "pointer"
};

const card = {
  background: "#111827",
  padding: "10px",
  marginTop: "10px",
  borderRadius: "10px"
};
